impl Register {
    /// Every value, in discriminant order.
    pub fn values() -> impl ExactSizeIterator<Item = Register> + DoubleEndedIterator + Clone {
        REGISTER_VALUES.iter().copied()
    }

    /// The value with discriminant `i`.
    pub fn from_index(i: usize) -> Option<Register> {
        REGISTER_VALUES.get(i).copied()
    }

    /// The spec's name.
    pub fn name(self) -> &'static str {
        REGISTER_NAMES[self as usize]
    }

    /// The value with this spec name.
    pub fn from_name(name: &str) -> Option<Register> {
        REGISTER_BY_NAME
            .binary_search_by(|&i| REGISTER_NAMES[i as usize].cmp(name))
            .ok()
            .and_then(|k| Self::from_index(REGISTER_BY_NAME[k] as usize))
    }
}

